document.addEventListener('touchmove',e=>{if(!homeTouch||e.touches.length!==1)return;const t=e.touches[0],dx=t.clientX-homeTouch.x,dy=t.clientY-homeTouch.y;if(Math.max(Math.abs(dx),Math.abs(dy))<3)return;const horizontal=Math.abs(dx)>Math.abs(dy),delta=horizontal?dx:dy;let el=homeTouch.target,canScroll=false;while(el&&el.nodeType===1){const css=getComputedStyle(el),overflow=horizontal?css.overflowX:css.overflowY,max=horizontal?el.scrollWidth-el.clientWidth:el.scrollHeight-el.clientHeight,pos=horizontal?el.scrollLeft:el.scrollTop;if(/auto|scroll/.test(overflow)&&max>1){canScroll=delta>0?pos>1:pos<max-1;break}el=el.parentElement}if(!canScroll&&e.cancelable)e.preventDefault();homeTouch.x=t.clientX;homeTouch.y=t.clientY},{passive:false});
