function motionFireworks(node){const dot=node.querySelector('.motion-dot'),rect=dot.getBoundingClientRect();function burst(size,color,delay){const canvas=document.createElement('canvas');canvas.width=440;canvas.height=440;canvas.setAttribute('aria-hidden','true');canvas.className='home-firework-overlay';canvas.style.cssText=`position:fixed;width:${137.5*size}px;height:${137.5*size}px;left:${rect.left+rect.width/2}px;top:${rect.top+rect.height/2}px;transform:translate(-50%,-50%);pointer-events:none;z-index:9999`;document.body.appendChild(canvas);const ctx=canvas.getContext('2d');const start=performance.now()+delay;function draw(now){if(!canvas.isConnected)return;if(!dot.isConnected){canvas.remove();return}const anchor=dot.getBoundingClientRect();canvas.style.left=(anchor.left+anchor.width/2)+'px';canvas.style.top=(anchor.top+anchor.height/2)+'px';const t=(now-start)/1500;if(t<0){requestAnimationFrame(draw);return}if(t>=1){canvas.remove();return}ctx.clearRect(0,0,440,440);ctx.save();ctx.translate(220,220);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=5;const radius=175*(1-Math.pow(1-t,2));for(let i=0;i<80;i++){const angle=i/80*Math.PI*2;const scale=1;const head=radius*scale;const tail=Math.max(0,head-(18+radius*.38));ctx.globalAlpha=Math.min(1,t*12)*Math.pow(1-t,.65);ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(Math.cos(angle)*tail,Math.sin(angle)*tail);ctx.lineTo(Math.cos(angle)*head,Math.sin(angle)*head);ctx.stroke();for(let j=0;j<6;j++){const r=tail+(head-tail)*j/5;ctx.globalAlpha=Math.min(1,t*12)*Math.pow(1-t,.65)*(.3+.7*Math.abs(Math.sin(j*7+t*35)));ctx.beginPath();ctx.arc(Math.cos(angle)*r,Math.sin(angle)*r,j===5?1.7:1,0,Math.PI*2);ctx.fill()}}ctx.restore();requestAnimationFrame(draw)}requestAnimationFrame(draw)}burst(1,getComputedStyle(dot).getPropertyValue('--card-purple-strong').trim()||'#AA94CF',0);burst(.5,'#F06464',0);burst(.75,getComputedStyle(dot).getPropertyValue('--card-white').trim()||'#FFFFFF',0)}


